from pathlib import Path
import subprocess, base64

BASE = "958b1a5"

head = subprocess.check_output(
    ["git", "rev-parse", "--short", "HEAD"],
    text=True,
).strip()

if head != BASE:
    raise SystemExit(
        f"Wrong baseline: HEAD is {head}, expected {BASE}."
    )

mobile_path = Path(
    "components/portal/mobile-portal-navigation.tsx"
)
layout_path = Path(
    "app/(portal)/layout.tsx"
)

if not mobile_path.exists() or not layout_path.exists():
    raise SystemExit(
        "Expected mobile navigation/layout files are missing."
    )

layout = layout_path.read_text(
    encoding="utf-8"
)

old_css = """                .portal-left-shell {
                  display: none !important;
                }"""

new_css = """                .portal-left-shell {
                  display: contents !important;
                }

                .portal-left-shell > aside {
                  display: none !important;
                }"""

if layout.count(old_css) != 1:
    raise SystemExit(
        "Mobile portal-left-shell CSS matcher failed."
    )

layout = layout.replace(
    old_css,
    new_css,
    1,
)

old_mount = """            <MobilePortalNavigation
              unreadMessageCount={
                context.unreadMessageCount
              }
              isStaff={
                context.isStaff
              }
            />"""

new_mount = """            <MobilePortalNavigation
              unreadMessageCount={
                context.unreadMessageCount
              }
              unreadForumCount={
                unreadForumCount
              }
              isStaff={
                context.isStaff
              }
            />"""

if layout.count(old_mount) != 1:
    raise SystemExit(
        "MobilePortalNavigation mount matcher failed."
    )

layout = layout.replace(
    old_mount,
    new_mount,
    1,
)

replacement = base64.b64decode(
    ""
).decode("utf-8")

mobile_path.write_text(
    replacement,
    encoding="utf-8",
)
layout_path.write_text(
    layout,
    encoding="utf-8",
)

print("✓ Fixed mobile modal visibility")
print("✓ Mobile panel uses PNG icons")
print("✓ PNG icons inherit current skin filter")
print("✓ Rules + expansion restored")
print("✓ Economy & Crafting + expansion restored")
print("✓ Forum original + / favourites / recent menu reused")
print("✓ Legal & Safety expansion restored")
print("✓ Friends / Private Location / Manage Order / Sanctions policies preserved")
print("✓ Forum unread count passed into mobile menu")
print("")
print("No SQL and no npm install required.")
print("Run: npm run build")
